// Before — the _state / asStateFlow() ceremony
class Before {
    private val _state = MutableStateFlow(Loading)
    val state: StateFlow<UiState> = _state.asStateFlow()
}

// After — one property, subtype visible only in-scope
class After {
    val state: StateFlow<UiState> field = MutableStateFlow(Loading)
    fun load() { state.update { Loading } }   // mutable API inside
}
// Outside, only StateFlow<UiState> — read-only.
